```rust
use gimpel::{Window, Point};

fn main() {
    let window = Window::new(
        vec![Point::new(100, 100), Point::new(400, 400)],
        200, 200,
        Some(4.0),
        None,
    );

    loop {
        window.draw_line(
            Point::new(100, 100),
            Point::new(300, 300),
            vec![0.0, 0.0, 0.0],
            1.0,
        );

        window.check_events();
    }
}
```
